const express = require('express');
const fs = require('fs');
const path = require('path');
const os = require('os');
const crypto = require('crypto');
const matter = require('gray-matter');
const cron = require('node-cron');
const backup = require('./backup');
const db = require('./db');

const app = express();

// ── Security: CORS — restrict to localhost origins ────────────────────────────
const ALLOWED_ORIGINS = new Set([
  'http://localhost:3847',
  'http://localhost:5173',   // Vite dev
  'http://localhost:3000',
  'http://localhost:8080',
  'http://127.0.0.1:3847',
  'http://127.0.0.1:5173',
  'http://127.0.0.1:3000',
  'http://127.0.0.1:8080',
]);

app.use((req, res, next) => {
  const origin = req.headers.origin;
  if (origin && ALLOWED_ORIGINS.has(origin)) {
    res.header('Access-Control-Allow-Origin', origin);
  } else if (!origin) {
    // Same-origin or non-browser client — no CORS header needed
  }
  res.header('Access-Control-Allow-Methods', 'GET, POST, PUT, DELETE, OPTIONS');
  res.header('Access-Control-Allow-Headers', 'Content-Type');
  if (req.method === 'OPTIONS') return res.sendStatus(204);
  next();
});

// ── Security: Localhost-only guard ────────────────────────────────────────────
app.use((req, res, next) => {
  // Webhook triggers are accessible externally (validated by secret)
  if (req.path.startsWith('/api/webhooks/trigger/')) return next();
  const ip = req.ip || req.connection?.remoteAddress || '';
  const isLocal = ip === '127.0.0.1' || ip === '::1' || ip === '::ffff:127.0.0.1' || ip === 'localhost';
  if (!isLocal) {
    return res.status(403).json({ error: 'Polyglot is local-only' });
  }
  next();
});

// ── Security: Rate limiting (in-memory, simple) ──────────────────────────────
const rateLimitMap = new Map();
const RATE_LIMIT_WINDOW = 60_000; // 1 minute
const RATE_LIMITS = {
  heavy: 10,   // AI chat, orchestration runs, playground — 10/min
  write: 60,   // file writes, creates, deletes — 60/min
  read: 200,   // reads, listings — 200/min
};

function rateLimit(tier) {
  const max = RATE_LIMITS[tier] || RATE_LIMITS.read;
  return (req, res, next) => {
    const key = `${tier}:${req.ip}`;
    const now = Date.now();
    let entry = rateLimitMap.get(key);
    if (!entry || now - entry.start > RATE_LIMIT_WINDOW) {
      entry = { start: now, count: 0 };
      rateLimitMap.set(key, entry);
    }
    entry.count++;
    if (entry.count > max) {
      return res.status(429).json({ error: `Rate limit exceeded (${max}/${RATE_LIMIT_WINDOW / 1000}s)` });
    }
    next();
  };
}

// Cleanup stale entries every 5 minutes
setInterval(() => {
  const now = Date.now();
  for (const [key, entry] of rateLimitMap) {
    if (now - entry.start > RATE_LIMIT_WINDOW * 2) rateLimitMap.delete(key);
  }
}, 300_000);

// ── Security: Helmet-like headers ────────────────────────────────────────────
app.use((req, res, next) => {
  res.setHeader('X-Content-Type-Options', 'nosniff');
  res.setHeader('X-Frame-Options', 'DENY');
  res.setHeader('Referrer-Policy', 'strict-origin-when-cross-origin');
  next();
});

app.use(express.json({ limit: '2mb' }));
// Serve built React frontend, fallback to legacy public/
const distPath = path.join(__dirname, '..', 'public-dist');
const legacyPath = path.join(__dirname, '..', 'public');
const staticPath = fs.existsSync(distPath) ? distPath : legacyPath;
app.use(express.static(staticPath));

