1705	// Topological sort helper
1706	function topoSort(nodes, edges) {
1707	  const inDegree = {};
1708	  const adj = {};
1709	  for (const n of nodes) { inDegree[n.id] = 0; adj[n.id] = []; }
1710	  for (const e of edges) {
1711	    adj[e.source].push(e.target);
1712	    inDegree[e.target] = (inDegree[e.target] || 0) + 1;
1713	  }
1714	  const queue = nodes.filter(n => inDegree[n.id] === 0).map(n => n.id);
1715	  const order = [];
1716	  while (queue.length) {
1717	    const id = queue.shift();
1718	    order.push(id);
1719	    for (const next of adj[id]) {
1720	      inDegree[next]--;
1721	      if (inDegree[next] === 0) queue.push(next);
1722	    }
1723	  }
1724	  return order;
1725	}
