1727	// Level-based grouping for parallel execution
1728	function topoLevels(nodes, edges) {
1729	  const inDegree = {};
1730	  const adj = {};
1731	  for (const n of nodes) { inDegree[n.id] = 0; adj[n.id] = []; }
1732	  for (const e of edges) {
1733	    adj[e.source] = adj[e.source] || [];
1734	    adj[e.source].push(e.target);
1735	    inDegree[e.target] = (inDegree[e.target] || 0) + 1;
1736	  }
1737	  const levels = [];
1738	  let queue = nodes.filter(n => inDegree[n.id] === 0).map(n => n.id);
1739	  while (queue.length) {
1740	    levels.push([...queue]);
1741	    const nextQueue = [];
1742	    for (const id of queue) {
1743	      for (const next of (adj[id] || [])) {
1744	        inDegree[next]--;
1745	        if (inDegree[next] === 0) nextQueue.push(next);
1746	      }
1747	    }
1748	    queue = nextQueue;
1749	  }
1750	  return levels;
1751	}
